use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn determine_field_context (symbol : & str , integer : i32) -> String { let symbol_lower = symbol . to_lowercase () ; if symbol_lower . contains ("version") { format ! ("version_field_{}" , integer) } else if symbol_lower . contains ("size") || symbol_lower . contains ("len") { format ! ("size_field_{}" , integer) } else if symbol_lower . contains ("index") || symbol_lower . contains ("offset") { format ! ("index_field_{}" , integer) } else if symbol_lower . contains ("hash") || symbol_lower . contains ("sha") { format ! ("hash_field_{}" , integer) } else if symbol_lower . contains ("bit") || symbol_lower . contains ("mask") { format ! ("bitfield_{}" , integer) } else if symbol_lower . contains ("error") || symbol_lower . contains ("code") { format ! ("error_field_{}" , integer) } else if symbol_lower . contains ("id") || symbol_lower . contains ("identifier") { format ! ("id_field_{}" , integer) } else if symbol_lower . contains ("count") || symbol_lower . contains ("num") { format ! ("counter_field_{}" , integer) } else { format ! ("generic_field_{}" , integer) } }
}